async function start(point){if(!B.isThreeMode()){await B.setWorkspaceMode('3d');if(!B.getViewer()){notify('Walkthrough needs the 3D view to load');return;}}if(!walking){world=window.KERN_WALK.create(B.currentGeometry());scope=currentBuilding().id;yaw=targetYaw=0;pitch=targetPitch=0;vx=vy=roll=0;gait=window.KERN_GAIT.create();crouched=crouchToggle=false;eyeHeight=eyeFrom=1.6278874;eyeStart=performance.now();}if(point){const q=world.supported({x:point.x,y:point.y,z:point.z});if(!q){notify('Choose a clear, walkable floor position');return;}world.setState(q);}resetTransient(true);walking=true;button.setAttribute('aria-pressed','true');hud.hidden=false;document.body.classList.add('walking');last=performance.now();cancelAnimationFrame(raf);tick(last);captureMouse();}
function captureMouse(){if(!walking||!B.isThreeMode())return;const canvas=$('threeviewport').querySelector('canvas');if(canvas?.requestPointerLock){try{const p=canvas.requestPointerLock();p?.catch(()=>notify('Click the 3D view to capture the mouse'));}catch{notify('Click the 3D view to capture the mouse');}}}
