window.addEventListener('keydown',e=>{if(walking||!B.isThreeMode()||isTypingTarget(e.target)||document.querySelector('dialog[open]'))return;const k=e.key.toLowerCase();if((e.ctrlKey||e.metaKey)&&['c','x','v','z','y'].includes(k)){e.preventDefault();e.stopImmediatePropagation();if(e.repeat)return;if(k==='z')e.shiftKey?redo():undo();else if(k==='y')redo();else KERN_OBJECT_UI.clipboard(k);}else if(['Delete','Backspace'].includes(e.key)&&selected){e.preventDefault();deleteSelection();}},true);
